#!/bin/sh
# Copyright-free demo: sunset panorama wrapped round the car + robot on hood/bumper/fenders + star on the tailgate.
# Output: ../../output/myl_demo.png ; compare with expected_myl_demo.png (should be pixel-identical).
# All inputs are generated by tools/make_demo_images.py.
cd "$(dirname "$0")"
python3 ../../make_wrap.py --bg bg_sunset.jpg \
  --front robot.png --front-face 335,110,565,260 \
  --tailgate star.png --name myl_demo.png "$@"
